  "missing": "",
  "outside": "",
  "check_question": "What is the kinetic energy of a particle with mass $2\\text{ kg}$ and speed $3\\text{ m/s}$?",
  "check_answer": "9 J",
  "check_concept": "work-energy-theorem"
}

{
